-- ---------------------------------------------------------------------------
-- Marketing OS — manual tasks (hand-assigned work that no workflow generates)
--
-- Until now EVERY marketing task was generated by the workflow engine:
-- `workflow_role_tasks` is bound to a content item (subject_id NOT NULL, at most
-- ONE open row per item), owned by a ROLE rather than a person, and closing one
-- ADVANCES the pinned path. That is deliberate and stays exactly as it is.
--
-- What it cannot express is the ordinary coordination work a manager or the CEO
-- hands to a person: «اعرضي حملة مينا ٥٢ يوم الأحد», «جهّزي عرض المحتوى الشهري».
-- Those have no workflow, no step, no single content subject, several can be
-- open for the same person at once, and closing one advances nothing. Forcing
-- them into workflow_role_tasks would break the one-open-per-subject invariant,
-- the five-role CHECK, and the advance-on-close RPC.
--
-- So they get their own pair of tables, surfaced in the SAME «مهامي» queue:
--   mos_task_series  — a repeating task's rule + template (daily/weekly/monthly)
--   mos_manual_tasks — the task itself; one-off, or one occurrence of a series
--
-- Authorization follows the module's posture exactly: RLS is the boundary and
-- capabilities are DATA. A new `assign_task` capability means "assign work to
-- OTHER people"; anyone who can read the workspace may always create a task for
-- THEMSELVES. The CEO holds `assign_task` — it is seeded here — even though the
-- CEO deliberately does not hold the broad `assign` (workflow reassignment).
-- ---------------------------------------------------------------------------

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. The capability. Capabilities are rows, not code — a later admin edit in
--    Settings → Roles and permissions can grant or revoke it per role.
-- ---------------------------------------------------------------------------

INSERT INTO public.role_capabilities (role_id, capability)
SELECT r.id, 'assign_task'
FROM public.roles r
WHERE r.key IN ('mos_marketing_manager', 'mos_ceo', 'mos_ops_supervisor')
ON CONFLICT (role_id, capability) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 2. Series — the recurrence rule for a repeating task
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.mos_task_series (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title              text NOT NULL,
  details            text,
  assignee_user_id   uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  created_by_user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE SET NULL,

  -- Optional context. All four are independent: a task may hang off a campaign,
  -- a content item, a goal, a project, several, or nothing at all.
  campaign_id uuid REFERENCES public.mos_campaigns(id) ON DELETE SET NULL,
  content_id  uuid REFERENCES public.mos_content(id)   ON DELETE SET NULL,
  goal_id     uuid REFERENCES public.mos_goals(id)     ON DELETE SET NULL,
  -- all_projects record id (JSONB in `records`: no FK possible) — same shape and
  -- same caveat as mos_content.project_id.
  project_id  uuid,

  freq        text     NOT NULL,
  -- Every N days / weeks / months.
  interval_n  integer  NOT NULL DEFAULT 1,
  -- Weekly only. Postgres DOW: 0 = Sunday … 6 = Saturday. Sunday first, because
  -- the Saudi work week starts on Sunday.
  byweekday   smallint[] NOT NULL DEFAULT '{}',
  -- Monthly only. 29/30/31 clamp to the last day of a short month rather than
  -- silently skipping February.
  bymonthday  smallint,
  -- The local time of day the occurrence is due, in Asia/Riyadh.
  due_time    time     NOT NULL DEFAULT '12:00',
  starts_on   date     NOT NULL DEFAULT current_date,
  ends_on     date,
  -- Pausing is hide-not-erase, like goals and audiences: the rule stops
  -- generating, already-open occurrences stay put.
  is_active   boolean  NOT NULL DEFAULT true,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_task_series_freq_check') THEN
    ALTER TABLE public.mos_task_series ADD CONSTRAINT mos_task_series_freq_check
      CHECK (freq IN ('daily','weekly','monthly'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_task_series_interval_check') THEN
    ALTER TABLE public.mos_task_series ADD CONSTRAINT mos_task_series_interval_check
      CHECK (interval_n BETWEEN 1 AND 52);
  END IF;
  -- A weekly rule with no weekday would generate nothing at all — a rule that
  -- silently never fires is worse than a refused save.
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_task_series_weekly_check') THEN
    ALTER TABLE public.mos_task_series ADD CONSTRAINT mos_task_series_weekly_check
      CHECK (freq <> 'weekly' OR array_length(byweekday, 1) >= 1);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_task_series_monthly_check') THEN
    ALTER TABLE public.mos_task_series ADD CONSTRAINT mos_task_series_monthly_check
      CHECK (freq <> 'monthly' OR (bymonthday BETWEEN 1 AND 31));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_task_series_window_check') THEN
    ALTER TABLE public.mos_task_series ADD CONSTRAINT mos_task_series_window_check
      CHECK (ends_on IS NULL OR ends_on >= starts_on);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_mos_task_series_active
  ON public.mos_task_series(is_active) WHERE is_active;

DROP TRIGGER IF EXISTS mos_task_series_touch_tg ON public.mos_task_series;
CREATE TRIGGER mos_task_series_touch_tg
  BEFORE UPDATE ON public.mos_task_series
  FOR EACH ROW EXECUTE FUNCTION public.mos_tg_touch_updated_at();

-- ---------------------------------------------------------------------------
-- 3. The tasks themselves
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.mos_manual_tasks (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- NULL for a one-off. Set (with occurrence_on) for a generated occurrence.
  series_id          uuid REFERENCES public.mos_task_series(id) ON DELETE SET NULL,
  occurrence_on      date,

  title              text NOT NULL,
  details            text,
  assignee_user_id   uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  created_by_user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE SET NULL,

  campaign_id uuid REFERENCES public.mos_campaigns(id) ON DELETE SET NULL,
  content_id  uuid REFERENCES public.mos_content(id)   ON DELETE SET NULL,
  goal_id     uuid REFERENCES public.mos_goals(id)     ON DELETE SET NULL,
  project_id  uuid,

  -- 'done' is the end of it: a manual task is coordination, not a workflow
  -- stage, so there is no submit → approve loop and no round counter.
  status      text NOT NULL DEFAULT 'open',
  due_at      timestamptz,
  done_note   text,
  closed_at   timestamptz,
  closed_by_user_id uuid REFERENCES public.users(id) ON DELETE SET NULL,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_manual_tasks_status_check') THEN
    ALTER TABLE public.mos_manual_tasks ADD CONSTRAINT mos_manual_tasks_status_check
      CHECK (status IN ('open','done','cancelled'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_manual_tasks_title_check') THEN
    ALTER TABLE public.mos_manual_tasks ADD CONSTRAINT mos_manual_tasks_title_check
      CHECK (length(btrim(title)) > 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mos_manual_tasks_occurrence_check') THEN
    ALTER TABLE public.mos_manual_tasks ADD CONSTRAINT mos_manual_tasks_occurrence_check
      CHECK ((series_id IS NULL) = (occurrence_on IS NULL));
  END IF;
END $$;

-- The idempotency key for generation: one task per series per occurrence date,
-- so the materializer below can be called on every page load without ever
-- producing a duplicate.
CREATE UNIQUE INDEX IF NOT EXISTS uq_mos_manual_tasks_occurrence
  ON public.mos_manual_tasks(series_id, occurrence_on)
  WHERE series_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_mos_manual_tasks_assignee
  ON public.mos_manual_tasks(assignee_user_id) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_mos_manual_tasks_due
  ON public.mos_manual_tasks(due_at) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_mos_manual_tasks_creator
  ON public.mos_manual_tasks(created_by_user_id);
CREATE INDEX IF NOT EXISTS idx_mos_manual_tasks_campaign
  ON public.mos_manual_tasks(campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_mos_manual_tasks_content
  ON public.mos_manual_tasks(content_id) WHERE content_id IS NOT NULL;

DROP TRIGGER IF EXISTS mos_manual_tasks_touch_tg ON public.mos_manual_tasks;
CREATE TRIGGER mos_manual_tasks_touch_tg
  BEFORE UPDATE ON public.mos_manual_tasks
  FOR EACH ROW EXECUTE FUNCTION public.mos_tg_touch_updated_at();

-- ---------------------------------------------------------------------------
-- 4. Column-level guard
--
-- RLS gates the ROW; it cannot say "the assignee may close this task but may not
-- re-word it, move its due date, or hand it to somebody else". This trigger
-- says exactly that, so the UPDATE policy can stay simple without the assignee
-- being able to edit their way out of the work.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.mos_tg_manual_task_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_me uuid := public.wassell_app_user_id(auth.uid());
BEGIN
  -- Managers/CEO (assign_task) and the person who created the task get the
  -- full edit. Admins are covered inside wassell_mos_can.
  IF public.wassell_mos_can('assign_task') OR OLD.created_by_user_id = v_me THEN
    RETURN NEW;
  END IF;

  IF OLD.assignee_user_id IS DISTINCT FROM v_me THEN
    RAISE EXCEPTION 'MOS:TASK_NOT_YOURS';
  END IF;

  IF NEW.title              IS DISTINCT FROM OLD.title
     OR NEW.details            IS DISTINCT FROM OLD.details
     OR NEW.assignee_user_id   IS DISTINCT FROM OLD.assignee_user_id
     OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
     OR NEW.due_at             IS DISTINCT FROM OLD.due_at
     OR NEW.campaign_id        IS DISTINCT FROM OLD.campaign_id
     OR NEW.content_id         IS DISTINCT FROM OLD.content_id
     OR NEW.goal_id            IS DISTINCT FROM OLD.goal_id
     OR NEW.project_id         IS DISTINCT FROM OLD.project_id
     OR NEW.series_id          IS DISTINCT FROM OLD.series_id
     OR NEW.occurrence_on      IS DISTINCT FROM OLD.occurrence_on
  THEN
    RAISE EXCEPTION 'MOS:TASK_FIELD_LOCKED';
  END IF;

  -- Cancelling is the assigner's call. The assignee finishes work or leaves it
  -- open and visible; they cannot make it disappear.
  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    RAISE EXCEPTION 'MOS:TASK_CANCEL_DENIED';
  END IF;

  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS mos_manual_tasks_guard_tg ON public.mos_manual_tasks;
CREATE TRIGGER mos_manual_tasks_guard_tg
  BEFORE UPDATE ON public.mos_manual_tasks
  FOR EACH ROW EXECUTE FUNCTION public.mos_tg_manual_task_guard();

-- ---------------------------------------------------------------------------
-- 5. RLS
--
-- Read = anyone who can read the workspace, matching every other mos_* table
-- (the team board shows everyone's queue by design).
-- Insert = assign_task for other people; ALWAYS allowed for yourself.
-- Update/Delete = assign_task, the creator, or (narrowed by the guard above)
-- the assignee.
-- ---------------------------------------------------------------------------

ALTER TABLE public.mos_task_series   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mos_manual_tasks  ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS mos_task_series_read ON public.mos_task_series;
CREATE POLICY mos_task_series_read ON public.mos_task_series
  FOR SELECT TO authenticated
  USING (public.wassell_mos_can('read'));

DROP POLICY IF EXISTS mos_task_series_ins ON public.mos_task_series;
CREATE POLICY mos_task_series_ins ON public.mos_task_series
  FOR INSERT TO authenticated
  WITH CHECK (
    created_by_user_id = public.wassell_app_user_id(auth.uid())
    AND (
      public.wassell_mos_can('assign_task')
      OR assignee_user_id = public.wassell_app_user_id(auth.uid())
    )
  );

DROP POLICY IF EXISTS mos_task_series_upd ON public.mos_task_series;
CREATE POLICY mos_task_series_upd ON public.mos_task_series
  FOR UPDATE TO authenticated
  USING (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
  )
  WITH CHECK (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
  );

DROP POLICY IF EXISTS mos_task_series_del ON public.mos_task_series;
CREATE POLICY mos_task_series_del ON public.mos_task_series
  FOR DELETE TO authenticated
  USING (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
  );

DROP POLICY IF EXISTS mos_manual_tasks_read ON public.mos_manual_tasks;
CREATE POLICY mos_manual_tasks_read ON public.mos_manual_tasks
  FOR SELECT TO authenticated
  USING (public.wassell_mos_can('read'));

DROP POLICY IF EXISTS mos_manual_tasks_ins ON public.mos_manual_tasks;
CREATE POLICY mos_manual_tasks_ins ON public.mos_manual_tasks
  FOR INSERT TO authenticated
  WITH CHECK (
    created_by_user_id = public.wassell_app_user_id(auth.uid())
    AND (
      public.wassell_mos_can('assign_task')
      OR assignee_user_id = public.wassell_app_user_id(auth.uid())
    )
  );

DROP POLICY IF EXISTS mos_manual_tasks_upd ON public.mos_manual_tasks;
CREATE POLICY mos_manual_tasks_upd ON public.mos_manual_tasks
  FOR UPDATE TO authenticated
  USING (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
    OR assignee_user_id   = public.wassell_app_user_id(auth.uid())
  )
  WITH CHECK (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
    OR assignee_user_id   = public.wassell_app_user_id(auth.uid())
  );

DROP POLICY IF EXISTS mos_manual_tasks_del ON public.mos_manual_tasks;
CREATE POLICY mos_manual_tasks_del ON public.mos_manual_tasks
  FOR DELETE TO authenticated
  USING (
    public.wassell_mos_can('assign_task')
    OR created_by_user_id = public.wassell_app_user_id(auth.uid())
  );

-- ---------------------------------------------------------------------------
-- 6. The materializer — turns a rule into real task rows
--
-- pg_cron is NOT enabled on wassell-prod (see CLAUDE.md, decks watchdog), so
-- generation is pull-based: the task list calls this before it reads. It is
-- SECURITY DEFINER (the series was authorized when it was created, not on every
-- occurrence), bounded (a fixed date window per series, so cost is O(series)),
-- and idempotent (uq_mos_manual_tasks_occurrence absorbs every re-run and every
-- concurrent caller). Backfill reaches 14 days back so a series still catches up
-- after a quiet week, and 14 days forward so a weekly task is visible before it
-- is due — but never so far that the queue fills with next month.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.mos_task_series_materialize()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  s          record;
  d          date;
  today      date;
  win_from   date;
  win_to     date;
  win_last   date;
  months     integer;
  target_day integer;
  hit        boolean;
  made       integer := 0;
BEGIN
  IF NOT public.wassell_mos_can('read') THEN
    RETURN 0;
  END IF;

  today  := (now() AT TIME ZONE 'Asia/Riyadh')::date;
  win_to := today + 14;

  FOR s IN
    SELECT * FROM public.mos_task_series
    WHERE is_active
      AND starts_on <= win_to
      AND (ends_on IS NULL OR ends_on >= today - 14)
  LOOP
    win_from := greatest(s.starts_on, today - 14);
    win_last := least(win_to, COALESCE(s.ends_on, win_to));

    d := win_from;
    WHILE d <= win_last LOOP
      IF s.freq = 'daily' THEN
        hit := (d - s.starts_on) % s.interval_n = 0;

      ELSIF s.freq = 'weekly' THEN
        -- Whole weeks since the rule's own start week, so "every 2 weeks" keeps
        -- its phase instead of drifting with the weekday list. The week is
        -- anchored to SUNDAY (subtracting DOW, where 0 = Sunday) — NOT
        -- date_trunc('week'), which is ISO/Monday-based and would put Sunday at
        -- the END of the week: "every 2 weeks on Sunday and Wednesday" would
        -- then split that pair across two different cycles. The Saudi work week
        -- starts on Sunday, so the pair must stay together.
        hit := EXTRACT(DOW FROM d)::smallint = ANY (s.byweekday)
               AND ((((d - EXTRACT(DOW FROM d)::integer)
                      - (s.starts_on - EXTRACT(DOW FROM s.starts_on)::integer)) / 7)
                    % s.interval_n) = 0;

      ELSE
        months := (EXTRACT(YEAR  FROM d)::integer - EXTRACT(YEAR  FROM s.starts_on)::integer) * 12
                + (EXTRACT(MONTH FROM d)::integer - EXTRACT(MONTH FROM s.starts_on)::integer);
        -- 31 on a 30-day month lands on the 30th rather than being skipped.
        target_day := least(
          s.bymonthday,
          EXTRACT(DAY FROM (date_trunc('month', d::timestamp) + interval '1 month - 1 day'))::integer
        );
        hit := months % s.interval_n = 0
               AND target_day = EXTRACT(DAY FROM d)::integer;
      END IF;

      IF hit THEN
        INSERT INTO public.mos_manual_tasks (
          series_id, occurrence_on, title, details,
          assignee_user_id, created_by_user_id,
          campaign_id, content_id, goal_id, project_id,
          due_at
        ) VALUES (
          s.id, d, s.title, s.details,
          s.assignee_user_id, s.created_by_user_id,
          s.campaign_id, s.content_id, s.goal_id, s.project_id,
          ((d + s.due_time) AT TIME ZONE 'Asia/Riyadh')
        )
        ON CONFLICT (series_id, occurrence_on) WHERE series_id IS NOT NULL DO NOTHING;
        IF FOUND THEN made := made + 1; END IF;
      END IF;
      d := d + 1;
    END LOOP;
  END LOOP;

  RETURN made;
END;
$function$;

REVOKE ALL ON FUNCTION public.mos_task_series_materialize() FROM public;
GRANT EXECUTE ON FUNCTION public.mos_task_series_materialize() TO authenticated, service_role;

COMMIT;
